package com.game_manager.gm.workflow; import com.game_manager.gm.common.entity.BaseEntity; import jakarta.persistence.*; import java.time.Instant; import java.util.UUID; import lombok.*; import org.hibernate.annotations.JdbcTypeCode; import org.hibernate.type.SqlTypes;
@Entity @Table(name="workflow_decisions") @Getter @Setter @NoArgsConstructor public class WorkflowDecision extends BaseEntity {@ManyToOne(fetch=FetchType.LAZY)@JoinColumn(name="instance_id",nullable=false)private WorkflowInstance instance;@ManyToOne(fetch=FetchType.LAZY)@JoinColumn(name="step_id",nullable=false)private WorkflowStep step;@JdbcTypeCode(SqlTypes.CHAR)@Column(name="actor_id",nullable=false,length=36)private UUID actorId;@Column(nullable=false,length=24)private String action;@Column(length=500)private String reason;@Column(name="from_step_key",nullable=false,length=60)private String fromStepKey;@Column(name="to_step_key",length=60)private String toStepKey;@Column(name="decided_at",nullable=false)private Instant decidedAt;}
